{
  "name": "Measuring Point Change Process",
  "resources": [
    {
      "name": "SP / PU / GO",
      "capacity": 1,
      "resource_type": "external_party"
    },
    {
      "name": "MPO",
      "capacity": 1,
      "resource_type": "department"
    }
  ],
  "events": [
    {
      "id": "evt_start_sp",
      "name": "Change requested by SP / PU / GO",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_end_req_sent",
      "name": "Send change request",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Change Request"
    },
    {
      "id": "evt_start_mpo_req",
      "name": "Receive change request from SP / PU / GO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Change Request"
    },
    {
      "id": "evt_start_mpo_internal",
      "name": "Internal MPO change caused",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_end_mpo_rejected",
      "name": "Send rejection notification",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Rejection Notification"
    },
    {
      "id": "evt_end_mpo_impl",
      "name": "Send implementation report",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Implementation Report"
    },
    {
      "id": "evt_end_mpo_failed",
      "name": "Send failure notification",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Failure Notification"
    },
    {
      "id": "evt_start_sp_rejected",
      "name": "Receive rejection",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Rejection Notification"
    },
    {
      "id": "evt_end_sp_rejected",
      "name": "Request rejected",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_start_sp_impl",
      "name": "Receive implementation report",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Implementation Report"
    },
    {
      "id": "evt_end_sp_impl",
      "name": "Change completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_start_sp_failed",
      "name": "Receive failure notification",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Failure Notification"
    },
    {
      "id": "evt_end_sp_failed",
      "name": "Change failed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_request_change",
      "name": "Request changes to MPO",
      "bpmn_type": "bpmn:Task",
      "resource_name": "SP / PU / GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_change_request"]
    },
    {
      "id": "task_review_request",
      "name": "Review change request",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_change_request"],
      "output_data_ids": []
    },
    {
      "id": "task_reject_request",
      "name": "Reject change of measuring point",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_confirm_request",
      "name": "Confirm request",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_perform_change",
      "name": "Perform measuring point change",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_report_impl",
      "name": "Report implementation to SP / PU / GO",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_impl_report"]
    },
    {
      "id": "task_notify_failure",
      "name": "Notify SP / PU / GO about failure of changes",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_failure_notice"]
    }
  ],
  "gateways": [
    {
      "id": "gw_start_mpo",
      "name": "Source of Change",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_mpo_start1",
          "condition": "Requested by SP / PU / GO"
        },
        {
          "flow_id": "sf_mpo_start2",
          "condition": "Caused by MPO"
        }
      ]
    },
    {
      "id": "gw_review_decision",
      "name": "Request Accepted?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_dec_reject",
          "condition": "Rejected"
        },
        {
          "flow_id": "sf_dec_confirm",
          "condition": "Confirmed"
        }
      ]
    },
    {
      "id": "gw_merge_changes",
      "name": "Merge Change Triggers",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_impl_result",
      "name": "Implementation Successful?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_impl_success",
          "condition": "Success"
        },
        {
          "flow_id": "sf_impl_failed",
          "condition": "Failure"
        }
      ]
    }
  ],
  "sequence_flows": [
    {
      "id": "sf_sp1",
      "source_id": "evt_start_sp",
      "target_id": "task_request_change",
      "condition_name": null
    },
    {
      "id": "sf_sp2",
      "source_id": "task_request_change",
      "target_id": "evt_end_req_sent",
      "condition_name": null
    },
    {
      "id": "sf_sp_rej1",
      "source_id": "evt_start_sp_rejected",
      "target_id": "evt_end_sp_rejected",
      "condition_name": null
    },
    {
      "id": "sf_sp_imp1",
      "source_id": "evt_start_sp_impl",
      "target_id": "evt_end_sp_impl",
      "condition_name": null
    },
    {
      "id": "sf_sp_fail1",
      "source_id": "evt_start_sp_failed",
      "target_id": "evt_end_sp_failed",
      "condition_name": null
    },
    {
      "id": "sf_mpo_start1",
      "source_id": "evt_start_mpo_req",
      "target_id": "gw_start_mpo",
      "condition_name": "Requested by SP / PU / GO"
    },
    {
      "id": "sf_mpo_start2",
      "source_id": "evt_start_mpo_internal",
      "target_id": "gw_start_mpo",
      "condition_name": "Caused by MPO"
    },
    {
      "id": "sf_mpo_rev",
      "source_id": "gw_start_mpo",
      "target_id": "task_review_request",
      "condition_name": "Requested by SP / PU / GO"
    },
    {
      "id": "sf_mpo_direct_change",
      "source_id": "gw_start_mpo",
      "target_id": "gw_merge_changes",
      "condition_name": "Caused by MPO"
    },
    {
      "id": "sf_review_to_gw",
      "source_id": "task_review_request",
      "target_id": "gw_review_decision",
      "condition_name": null
    },
    {
      "id": "sf_dec_reject",
      "source_id": "gw_review_decision",
      "target_id": "task_reject_request",
      "condition_name": "Rejected"
    },
    {
      "id": "sf_reject_to_end",
      "source_id": "task_reject_request",
      "target_id": "evt_end_mpo_rejected",
      "condition_name": null
    },
    {
      "id": "sf_dec_confirm",
      "source_id": "gw_review_decision",
      "target_id": "task_confirm_request",
      "condition_name": "Confirmed"
    },
    {
      "id": "sf_confirm_to_merge",
      "source_id": "task_confirm_request",
      "target_id": "gw_merge_changes",
      "condition_name": null
    },
    {
      "id": "sf_merge_to_perform",
      "source_id": "gw_merge_changes",
      "target_id": "task_perform_change",
      "condition_name": null
    },
    {
      "id": "sf_perform_to_gw",
      "source_id": "task_perform_change",
      "target_id": "gw_impl_result",
      "condition_name": null
    },
    {
      "id": "sf_impl_success",
      "source_id": "gw_impl_result",
      "target_id": "task_report_impl",
      "condition_name": "Success"
    },
    {
      "id": "sf_report_to_end",
      "source_id": "task_report_impl",
      "target_id": "evt_end_mpo_impl",
      "condition_name": null
    },
    {
      "id": "sf_impl_failed",
      "source_id": "gw_impl_result",
      "target_id": "task_notify_failure",
      "condition_name": "Failure"
    },
    {
      "id": "sf_notify_to_end",
      "source_id": "task_notify_failure",
      "target_id": "evt_end_mpo_failed",
      "condition_name": null
    }
  ],
  "pools": [
    {
      "id": "pool_sp",
      "name": "SP / PU / GO",
      "element_ids": [
        "evt_start_sp",
        "task_request_change",
        "evt_end_req_sent",
        "evt_start_sp_rejected",
        "evt_end_sp_rejected",
        "evt_start_sp_impl",
        "evt_end_sp_impl",
        "evt_start_sp_failed",
        "evt_end_sp_failed"
      ]
    },
    {
      "id": "pool_mpo",
      "name": "MPO",
      "element_ids": [
        "evt_start_mpo_req",
        "evt_start_mpo_internal",
        "gw_start_mpo",
        "task_review_request",
        "gw_review_decision",
        "task_reject_request",
        "evt_end_mpo_rejected",
        "task_confirm_request",
        "gw_merge_changes",
        "task_perform_change",
        "gw_impl_result",
        "task_report_impl",
        "evt_end_mpo_impl",
        "task_notify_failure",
        "evt_end_mpo_failed"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_change_request",
      "source_id": "evt_end_req_sent",
      "target_id": "evt_start_mpo_req",
      "name": "Change Request"
    },
    {
      "id": "mf_rejection",
      "source_id": "evt_end_mpo_rejected",
      "target_id": "evt_start_sp_rejected",
      "name": "Rejection Notification"
    },
    {
      "id": "mf_implementation",
      "source_id": "evt_end_mpo_impl",
      "target_id": "evt_start_sp_impl",
      "name": "Implementation Report"
    },
    {
      "id": "mf_failure",
      "source_id": "evt_end_mpo_failed",
      "target_id": "evt_start_sp_failed",
      "name": "Failure Notification"
    }
  ],
  "data_objects": [
    {
      "id": "data_change_request",
      "name": "Change Request"
    },
    {
      "id": "data_impl_report",
      "name": "Implementation Report"
    },
    {
      "id": "data_failure_notice",
      "name": "Failure Notification"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "minutes"
}
